export const faults={
 battery:{name:'Batería descargada',tests:['battery'],hint:'Compara tensión en reposo y durante el intento. Una batería puede mostrar tensión y no sostener la carga.',why:'La tensión cae bajo carga y el arranque gira demasiado despacio. En este caso se recupera la carga y se verifica la batería; en un carro real hay que investigar por qué se descargó.'},
 ground:{name:'Conexión de masa resistiva',tests:['battery','drop'],hint:'Si la batería sostiene tensión, mide lo que se pierde en el retorno de masa mientras circula corriente.',why:'La resistencia del retorno consume tensión que debería llegar al arranque. Se restablece la conexión y se repite la caída bajo carga.'},
 relay:{name:'Circuito de mando abierto',tests:['command'],hint:'Distingue la alimentación de potencia de la orden que llega al solenoide.',why:'Sin orden en el solenoide el motor de arranque no actúa. Este caso representa una apertura en el mando, no demuestra por sí solo qué interruptor o cable falló.'},
 spark:{name:'Encendido sin chispa',tests:['spark'],hint:'Que el cigüeñal gire no demuestra que exista encendido. Comprueba con el equipo de prueba simulado.',why:'Hay giro, combustible y compresión, pero falta encendido. El caso abstrae la reparación del circuito de encendido tras comprobarlo.'},
 fuel:{name:'Alimentación de combustible ausente',tests:['fuel'],hint:'El ruido de una bomba no confirma presión ni entrega. Consulta la prueba de alimentación.',why:'El motor gira y hay chispa, pero no llega combustible. Se restablece la alimentación; en la práctica se localiza antes la causa eléctrica o hidráulica.'},
 compression:{name:'Pérdida de compresión',tests:['compression'],hint:'Si hay giro, chispa y combustible, comprueba la capacidad de sellar el cilindro.',why:'La pérdida de estanqueidad impide la compresión necesaria en este modelo. Una medición baja requiere pruebas adicionales para distinguir válvulas, segmentos o junta.'},
 charge:{name:'Sistema de carga sin aporte',tests:['charge'],hint:'El motor puede arrancar con la energía de la batería aunque el sistema de carga no aporte.',why:'El motor arranca, pero la tensión no sube en el modelo convencional. La intervención representa restablecer el sistema de carga, después de revisar correa, conexiones y regulación.'}
};
export const pools={engine:['compression','spark','fuel'],electric:['battery','ground','relay','charge'],diagnosis:['battery','ground','relay','spark','fuel','compression']};
export const tests={battery:'Batería: reposo y bajo carga',drop:'Caída de tensión en masa',command:'Orden al solenoide',spark:'Prueba de encendido',fuel:'Alimentación de combustible',compression:'Compresión del cilindro',charge:'Tensión con motor en marcha'};
export function createCase(block='engine',random=Math.random){const pool=pools[block]||pools.engine;return {id:crypto.randomUUID(),block,fault:pool[Math.min(pool.length-1,Math.floor(Math.max(0,random())*pool.length))],key:'off',measured:[],diagnosed:false,repaired:false,done:false,hints:0,errors:0,events:[]};}
export function frame(s){const f=s.repaired?'':s.fault,attempt=s.key==='crank',cranks=attempt&&f!=='relay',slow=f==='battery'||f==='ground',eligible=!['battery','ground','relay','spark','fuel','compression'].includes(f),starts=cranks&&eligible,running=s.key==='run'&&s.started&&eligible,rpm=running?850:cranks?(slow?65:220):0;return {cranks,running:!!running,rpm,spark:rpm>0&&f!=='spark',fuel:f!=='fuel',compression:f==='compression'?3:11,rest:f==='battery'?11.6:12.6,loaded:!attempt?(f==='battery'?11.6:12.6):f==='battery'?7.8:f==='relay'?12.6:10.8,drop:cranks?(f==='ground'?2.8:.15):0,command:attempt&&f!=='relay',charge:running?(f==='charge'?12.3:14.2):null,starts,combustion:!!running||starts,status:s.key==='off'?'Contacto apagado':running?'Motor en marcha':!cranks?'No gira':slow?'Gira lentamente; no arranca':starts?'Gira y puede arrancar':'Gira, pero no arranca'};}
export function ignition(s,key){if(!['off','crank','run'].includes(key))return;s.key=key;if(key==='off')s.started=false;if(key==='crank')s.started=frame(s).starts;}
export const score=s=>Math.max(0,100-s.hints*10-s.errors*10);
export function measure(s,key){if(!tests[key])return '';const v=frame(s);if(key==='charge'&&!v.running)return 'Primero intenta arrancar y pasa a Marcha. Esta prueba necesita el motor funcionando.';if(key!=='charge'&&s.key!=='crank')return 'Selecciona Intentar arranque para tomar esta medición bajo las condiciones del ejercicio.';if(key==='compression'&&!v.cranks)return 'La prueba de compresión necesita giro; resuelve primero la falta de arranque.';if(!s.measured.includes(key))s.measured.push(key);const results={battery:`Reposo: ${v.rest.toFixed(1)} V. Durante intento: ${v.loaded.toFixed(1)} V.`,drop:`Masa: ${v.drop.toFixed(2)} V durante intento.${!v.cranks?' Sin giro/carga: este cero no certifica la conexión.':''}`,command:v.command?'Orden presente en el solenoide.':'No llega orden al solenoide.',spark:v.spark?'Encendido detectado por el comprobador simulado.':'No se detecta encendido durante el intento.',fuel:v.fuel?'Entrega presente en la prueba simulada.':'Entrega ausente en la prueba simulada.',compression:`Compresión: ${v.compression} bar en el cilindro didáctico; referencia de este banco: 11 bar.`,charge:`Motor en marcha: ${v.charge?.toFixed(1)} V; referencia del banco convencional: 14,2 V.`};s.events.push({type:'test',key,result:results[key]});return results[key];}
export function diagnose(s,choice){if(s.done||s.repaired)return 'Caso ya intervenido; verifica el resultado.';if(choice!==s.fault){s.errors++;return 'La hipótesis no coincide con las evidencias del caso. −10 puntos. Revisa las mediciones.';}if(!faults[s.fault].tests.every(k=>s.measured.includes(k)))return 'Hipótesis pendiente: reúne primero las mediciones que la sustentan.';s.diagnosed=true;return 'Diagnóstico sustentado. Ahora puedes aplicar la reparación simulada.';}
export function repair(s){if(!s.diagnosed)return 'Confirma un diagnóstico con mediciones antes de intervenir.';if(s.repaired)return 'La reparación ya está aplicada.';s.repaired=true;s.measured=[];s.key='off';s.started=false;s.events.push({type:'repair',fault:s.fault});return 'Reparación aplicada. Repite las mediciones relevantes, comprueba arranque y carga; después verifica.';}
export function verify(s){if(s.done)return true;const v=frame(s);const required=[...faults[s.fault].tests,'charge'];if(s.repaired&&v.running&&required.every(k=>s.measured.includes(k))){s.done=true;return true;}s.errors++;return false;}
